def find_components_4connectivity(grid):
    height, width = len(grid), len(grid[0])
    components = []
    visited = [[False]*width for _ in range(height)]

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 3 and not visited[r][c]:
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == 3 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(component)
    return components

